import base64
import json
from pathlib import Path

from astrbot.core.utils.astrbot_path import get_astrbot_plugin_data_path


def _d(s: str) -> str:
    """decode."""
    if not s:
        return s
    try:
        return base64.b64decode(s).decode("utf-8")
    except Exception:
        return s

